// Ensure drunkAmount is a number.  If not, initialize it to 0.
if (typeof data.drunkAmount !== 'number') {  data.drunkAmount = 0;}

// Get the daily goal from the configuration (Sub Workflow)
const dailyGoal = $('Get: Workflow Constants 1').first().json.config.dailyGoal;


const translations = {
  en: {
    goalReached:
      `🎉🎉🎉\n\nCongratulations! You reached your daily goal 👏👏👏\n\nDrank: ${data.drunkAmount} ml\n\nSee you tomorrow!`,

    exceededGoal:
      `🎉🎉🎉\n\nCongratulations! You reached your daily goal of ${dailyGoal} ml and even drank ${data.drunkAmount - dailyGoal} ml more.\nGreat job 👏👏👏\n\nSee you tomorrow!`
  },

  de: {
    goalReached:
      `🎉🎉🎉\n\nGratulation! Du hast dein Tagesziel erreicht 👏👏👏\n\nGetrunkene Menge: ${data.drunkAmount} ml\n\nBis morgen!`,

    exceededGoal:
      `🎉🎉🎉\n\nGratulation! Du hast dein Tagesziel von ${dailyGoal} ml erreicht und sogar ${data.drunkAmount - dailyGoal} ml mehr getrunken.\nTolle Leistung 👏👏👏\n\nBis morgen!`
  }
};

let text = translations[language].goalReached;

if (data.drunkAmount > dailyGoal) {
  text = translations[language].exceededGoal;
}

return [{
  json: {
    text: text
  }
}];

