// lock all workflows 
data.mainLock = true;
data.subLock = true;
data.aggroLock = true;

data.initFinished = false;

// ------------------------------------
// RESET ALL GLOBAL STATE
// ------------------------------------
Object.keys(data).forEach(key => {
  delete data[key];
});


// ------------------------------------
// DEFAULT VALUES
// ------------------------------------
Object.assign(data, {
  // init
  initFinished: true,
  firstMainRunDone: false,

  // reminder state
  goodMorningFinished: false,
  goodMorningMessageFinished: false,

  // counters
  unansweredFlowCount: 0,
  offset: 0,

  // drink tracking
  drunkAmount: 0,

  // collections
  pendingReminders: [],
  processedCallbacks: {},
  processedInputs: [],

  // model histories
  aggroMessagesHistory: [],
  modelMessagesHistory: [],

  // locks
  mainLock: false,
  mainLockTime: null,
  subLock: false,
  subLockTime: null,
  aggroLock: false,
  aggroLockTime: null    
});


// ------------------------------------
// RETURN DEBUG INFO
// ------------------------------------
return [{
  json: {
    success: true,
    message: "Global state reset complete",
    data
  }
}];

const data = $getWorkflowStaticData('global');

// Variable to store the amount of liquid consumed in milli liters.
if (data.drunkAmount === undefined) {
  data.drunkAmount = 0;
}

// Buffer to store pending reminder callbacks.
if (!data.pendingReminders) {
  data.pendingReminders = [];
}

// Flag to indicate whether the good morning message has been sent.
if (data.goodMorningMessageFinished === undefined) {
  data.goodMorningMessageFinished = false;
}

const isProd = $workflow.active === true 
                 || $execution?.mode === 'production'
                 || !!$input.first()?.json.__isProduction;
let bufferReset = false;
const debug = $('Get: Workflow Constants 1').first().json.config.debug;

// reset for local debugging
if (!isProd && debug){

  // counters
  data.unansweredFlowCount= 0;
  data.offset= 0;

  // drink tracking
  data.drunkAmount= 0;

  // collections
  data.pendingReminders= [];
  data.processedCallbacks= {};
  data.processedInputs= [];

  // model histories
  data.aggroMessagesHistory= [];
  data.modelMessagesHistory= [];
  bufferReset=true;
}

return [{
  json: {
    drunkAmount: data.drunkAmount,
    goodMorningMessageFinished: data.goodMorningMessageFinished,
    bufferReset :bufferReset,
    data
  }
}];

