const language = $('Get: Workflow Constants 1').first().json.config.language || 'en';

const current = $json.current;

let weather = "not available";

// Check if current weather data is available.
if (!current) {
  return [{
    json: {
      success: false,
      weather
    }
  }];
}

const temperature = current.temperature_2m;
const weatherCode = current.weather_code;

const labels = {
  en: {
    sunny: "sunny ☀️",
    partly: "partly cloudy 🌤️",
    cloudy: "cloudy ☁️",
    rainy: "rainy 🌧️"
  },
  de: {
    sunny: "sonnig ☀️",
    partly: "leicht bewölkt 🌤️",
    cloudy: "bewölkt ☁️",
    rainy: "regnerisch 🌧️"
  }
};

const t = labels[language] || labels.en;

// Weather mapping
if (weatherCode === 0) {
  weather = `${temperature}°C ${t.sunny}`;
} 
else if ([1, 2].includes(weatherCode)) {
  weather = `${temperature}°C ${t.partly}`;
}
else if (weatherCode === 3) {
  weather = `${temperature}°C ${t.cloudy}`;
}
else if (weatherCode >= 51 && weatherCode <= 67) {
  weather = `${temperature}°C ${t.rainy}`;
}

return [{
  json: {
    success: true,
    temperature,
    weather
  }
}];

const data = $getWorkflowStaticData('global');
const language = $('Get: Workflow Constants 1').first().json.config.language || 'en';

const header = `TRINK WASSER ‼️‼️‼️\n\n`;
let prompt = "";
const temperature =  $('Get: Workflow Constants 1').first().json.config.temperatureHot;
const weatherInfo = $json.weather
  ? `Aktuelles Wetter: ${$json.weather}`
  : "";


// ---------------------------
// GOOD MORNING MESSAGE
// ---------------------------
if (data.goodMorningMessageFinished === false) {

  prompt = `
    Erzeuge eine freundliche, motivierende Trink-Wasser-Erinnerung auf ${language} (Sprachcode).

    Regeln:
    - Beginne mit: "Guten Morgen! ☀️" bzw. "Good morning! ☀️" je nach Sprachcode
    - Leite gerne ein, dass du hier bist um zu helfen!
    - Danach Zeilenumbruch
    - Freundlicher, motivierender Ton
    - Erkläre kurz, warum Trinken wichtig ist
    - Nutze abwechslungsreich:
      - Allgemeinwissen
      - kurze Gesundheitsfakten
      - Motivation
    - Emojis erlaubt, aber sparsam einsetzen
    - wenn es passt Bulletpoints verwenden
    - 5 bis 6 kurze Sätze
    - Wetter natürlich einbauen, falls vorhanden
    - wenn über ${temperature} °C heiß, in den Vordergrung stellen z.B.Es wird heute extrem heiß!, nutze Zeilenumbrüche geschickt
    - Keine Begrüßung am Ende
    - Keine Alternativen
    - Keine Meta-Erklärung
    - Keine Einleitung oder Erklärung
    - Gib ausschließlich die fertige Nachricht zurück

    Format:
    - Am Ende IMMER ein Zeilenumbruch
    - Danach einen Hinweis wie:
    "👉 Vergiss nicht, deine Trinkmenge einzutragen..Sonst melde ich mich⚠️ 

    WICHTIG:
    - Sprachcode: "${language}" Finale Anwort IMMER in diese Sprache übersetzen

    ${weatherInfo}
    `.trim();

  data.goodMorningMessageFinished = true;

  return [{
    json: {
      prompt,
      goodMorningMessageFinished:data.goodMorningMessageFinished
    }
  }];
}



const promptNormal =  `
Erzeuge eine freundliche, motivierende Trink-Wasser-Erinnerung auf ${language} (Sprachcode)

Regeln:
- Beginne IMMER mit einem Slogan: z.B. "${header}" 
- Freundlicher, motivierender und/oder "cooler" Ton
- Erkläre kurz, warum Trinken wichtig ist
- Nutze abwechslungsreich:
  - Allgemeinwissen
  - kurze Gesundheitsfakten
  - Motivation
- Emojis erlaubt, aber sparsam einsetzen
- wenn es passt Bulletpoints verwenden
- 2 bis 4 kurze Sätze
- Keine Begrüßung am Ende
- Keine Alternativen
- Keine Meta-Erklärung
- Keine Einleitung oder Erklärung
- Gib ausschließlich die fertige Nachricht zurück
WICHTIG:
    - Sprachcode: "${language}" Finale Anwort IMMER in diese Sprache übersetzen!
`.trim();


if (  $json.success && ($json.temperature >  $('Get: Workflow Constants 1').first()      .json.config.temperatureHot )) {

  // ---------------------------
  // HOT WEATHER REMINDER
  // ---------------------------

   prompt = `${promptNormal}

             - Es wird heute über ${temperature} °C heiß, stell dies in den Vordergrund, nutze dafür Zeilenumbrüche geschickt
             - Wetter natürlich einbauen, falls vorhanden
            ${weatherInfo}
            `.trim();

} else {

  // ---------------------------
  // NORMAL REMINDER
  // ---------------------------
  prompt = promptNormal;
}

let promptUseHistory ="";

if ($('Get: Workflow Constants 1').first().json.config.usePromptHistory){
  const messageHistory =  data.modelMessagesHistory?.join('\n- ') || '';

  promptUseHistory = `
  WICHTIG:
  Vermeide ähnliche oder gleiche Formulierungen wie in diesen früheren Nachrichten.

  Bisherige Nachrichten:
  - ${messageHistory}

  Erzeuge nun eine neue, abwechslungsreiche Nachricht.
  `.trim();  

  prompt = `${prompt} 
            ${promptUseHistory}
            `.trim();

}

return [{
  json: {
    prompt : prompt
  }
}];

return [{
