    messageId: $('Telegram API: Send Callback Message').first().json.result.message_id,
    chatId: $('Telegram API: Send Callback Message').first().json.result.chat.id, 
    pendingReminders : data.pendingReminders ,
    sentAt:Date.now(),
    callbackPending: data.callbackPending,
    callbackPendingMsgId: data.callbackPendingMsgId
  }
}];

const data = $getWorkflowStaticData('global');

// If there are no pending reminders, exit.
if (!data.pendingReminders || data.pendingReminders.length === 0) {
  return [];
}

// Get the latest pending reminder.
const latest = data.pendingReminders[data.pendingReminders.length - 1];

// Filter the pending reminders to identify those that should be deleted.
// These are reminders that are not the latest and are not confirmed.
const toDelete = data.pendingReminders.filter((r, i) =>
  i !== data.pendingReminders.length - 1 && !r.confirmed
);

// Update the pending reminders array to retain only the latest and confirmed reminders.
data.pendingReminders = [
  latest,
  ...data.pendingReminders.filter(r => r.confirmed)
];

// Prepare the items for the n8n deleteMessage operation.
return toDelete.map(r => ({
  json: {
    chat_id: r.chatId,
    message_id: r.messageId
  }
}));

