const data = $getWorkflowStaticData('global');

const now = Date.now();

// Get the maximum lock time from the configuration.  This is a safety fallback
// estimated runtime of this path.
const MAX_LOCK_TIME  =  $input.first().json.config.deadLockMaxAggroSec * 1000;  

// wait for variables are initialized in first run
if (data.initFinished === undefined || data.initFinished === false) {
  console.log("[AGGRO] locked until init ready → exit");
  return [];  
}

// initial Main run still active
if (data.firstMainRunDone === false) {
  console.log("[AGGRO] firstMainRunDone still on going ") 
  return [];
}


// DEADLOCK RECOVERY
// If the workflow has crashed or was never released, check if the lock is stale.
if (data.aggroLock && data.aggroLockTime) {
  const age = now - data.aggroLockTime;
  if (age > MAX_LOCK_TIME) {
    console.log("[AGGRO] stale lock detected → resetting lock");
    data.aggroLock = false;
    data.aggroLockTime = null;
  }
}

// If the main lock is already active, exit.  This prevents multiple instances
// of the workflow from running concurrently.

if (data.mainLock) {
  console.log("[AGGRO] mainLock locked → exit");
  return [];
}

// sub active
if (data.subLock) {
  console.log("[AGGRO] subLock locked → exit");
  return [];
}

if (data.aggroLock) {
  console.log("[AGGRO] aggroLock locked → exit");
  return [];
}

// finally lock this path
data.aggroLock = true;
data.aggroLockTime = now;

return [{ json: $json }];

const data = $getWorkflowStaticData('global');

const now = Date.now();

// Get the maximum lock time from the configuration.  This is a safety fallback
// estimated runtime of the main path.
const MAX_LOCK_TIME = $('Get: Workflow Constants 1').first().json.config.deadLockMaxMainSec * 1000;

// DEADLOCK RECOVERY
// If the workflow has crashed or was never released, check if the lock is stale.
if (data.mainLock && data.mainLockTime) {
  // Calculate the age of the lock.
  const age = now - data.mainLockTime;

  // If the lock is older than the maximum allowed time, it's considered stale.
  if (age > MAX_LOCK_TIME) {
    console.log("[MAIN] stale lock detected → resetting lock");

    // Reset the lock to allow the workflow to proceed.
    data.mainLock = false;
    data.mainLockTime = null;
  }
}

// Check if the initialization is finished. If not, exit.
if (data.initFinished === undefined || data.initFinished === false) {
  console.log("[MAIN] locked until init ready → exit");
  return []; // Exit the workflow.
}

// If the main lock is already active, exit.  This prevents multiple instances
// of the workflow from running concurrently.
if (data.mainLock) {
  console.log("[MAIN] locked → exit");
  return []; // Exit the workflow.
}

// Set the main lock immediately to prevent concurrent execution.
data.mainLock = true;
data.mainLockTime = now;

// Return an array containing the current JSON data.
return [{ json: $json }];

const data = $getWorkflowStaticData('global');

const pendingCount =  data.pendingReminders?.length ?? 0;

if (data.unansweredFlowCount === undefined) {
  data.unansweredFlowCount = 0;
}

const unansweredCount =  data.pendingReminders.filter(r => r.confirmed=== false).length;
const maxCount = $('Get: Workflow Constants 3').first().json.config.aggressiveModeIgnoredMax
const debugTelegramMessage = `State:\n -> ${unansweredCount} unanswered  /  ${pendingCount} pending!\n -> unanswered counter: ${data.unansweredFlowCount}\n -> Start Aggro Mode after ${maxCount} skipped callbacks\n -> total drunk amount:  ${data.drunkAmount} ml\n\n`;


if (data.unansweredFlowCount > maxCount){
return [{
  json: {
    triggerAgression: true,
    pendingReminders : data.pendingReminders,
     unansweredFlowCount : data.unansweredFlowCount,
    unansweredCount: unansweredCount,
    pendingCount : pendingCount,
    debugTelegramMessage: debugTelegramMessage
  }
}];  
}else{
return [{
  json: {
    triggerAgression: false,
    pendingReminders : data.pendingReminders,
     unansweredFlowCount : data.unansweredFlowCount,
    unansweredCount: unansweredCount,
    pendingCount : pendingCount,
    debugTelegramMessage: debugTelegramMessage
  }
}];  
}

const data = $getWorkflowStaticData('global');
const language =  $('Get: Workflow Constants 3').first().json.config.language || 'en';

// aggroMessagesHistory will be used to produce more and more aggressive messages from the model
if (!data.aggroMessagesHistory) {
  data.aggroMessagesHistory = [];
}


const messageHistory =  data.aggroMessagesHistory?.join('\n- ') || '';

const prompt = `
Erzeuge eine direkte, motivierende Auforderung Wasser zu trinken anhand der bisherige Nachrichten in folgender Sprache / Sprachcode: "${language}"

aggresive, 
Hintergrund User hat die Menge an wasser nicht angegeben, was heißen kann das er nicht getrunken hat!

Regeln:
- Wenn es noch keine Bisherige Nachrichten gibt, dann erstelle eine Nachricht z.B.
  - "Hast du etwa vergessen Wasser zu trinken? Gib mir Feedback sonst nerve ich!"
  - "Schon wieder vergessen zu antworten?!"  
- Werd immer aggressiver mit der Anzahl an bisherigen Nachrichten
- Der Leser soll merken "Hey ich sollte die Menege an getrunkenen Wasser eingeben"
- Emojis erlaubt, aber sparsam einsetzen
- 1 bis 2 kurze Sätze
- Keine Begrüßung am Ende
