- Keine Meta-Erklärung
- Keine Einleitung oder Erklärung
- Gib ausschließlich die fertige Nachricht zurück
- denk an die Übersetzung: / Sprachcode: "${language}"

Bisherige Nachrichten:
- ${messageHistory}
`.trim();  


return [{
  json: {
    prompt:prompt   
  }
}];

const data = $getWorkflowStaticData('global');

// create History 
if (!data.modelMessagesHistory) {
  data.modelMessagesHistory = [];
}

// Max Buffer Size
const maxSize =  $('Get: Workflow Constants 1').first().json.config.modelMessagesHistoryMax || 10;

// Message from model
const message = $('Ollama API: Get LLM Response').first().json.response; 
// skip empty messages
if (message?.trim()) {

  // if full, remove oldest
  if (data.modelMessagesHistory.length >= maxSize) {
    data.modelMessagesHistory.shift();
  }

  // add new message
  data.modelMessagesHistory.push(message.trim());
}

return [{
  json: {
    message,
    historySize: data.modelMessagesHistory.length,
    history: data.modelMessagesHistory
  }
}];

const data = $getWorkflowStaticData('global');

const maxSize = $('Get: Workflow Constants 3').first().json.config.modelMessagesHistoryMax || 6;

// aggroMessagesHistory will be used to produce more and more aggressive messages from the model 
if (!data.aggroMessagesHistory) {
  data.aggroMessagesHistory = [];
}
const ollamaMessage = $input.first().json.response;
if (ollamaMessage?.trim()) {

  // remove older ones..
  if (data.aggroMessagesHistory.length >= maxSize) {
    data.aggroMessagesHistory.shift();
  }

  // add new message
  data.aggroMessagesHistory.push(ollamaMessage.trim());
}
return [{
  json: {  
    ollamaMessage :ollamaMessage,
    aggroMessagesHistory: data.aggroMessagesHistory
  }
}];

